import { existsSync, readdirSync, rmSync } from "node:fs";
import { join, resolve } from "node:path";

/**
 * Deletes stale `app.config` assets generated by expo-constants' Gradle task.
 *
 * The `createExpoConfig` Gradle task does not track `apps/mobile/.env` as an
 * input, so edits to the API/socket URL can be silently ignored (the APK keeps
 * the previous backend URL). Running this before a build forces regeneration.
 */
const projectRoot = resolve(process.cwd());
const repoRoot = resolve(projectRoot, "..", "..");
const targets = [
  join(projectRoot, "android", "app", "build"),
  join(repoRoot, "node_modules", ".pnpm"),
];

function walk(dir, depth = 0) {
  if (depth > 12) return;
  let entries;
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(full, depth + 1);
    } else if (entry.name === "app.config" && full.includes("expo-constants")) {
      rmSync(full, { force: true });
    }
  }
}

for (const target of targets) {
  if (existsSync(target)) walk(target);
}
console.log("Cleared stale expo app.config caches.");
